-- =====================================================
-- DZIEŃ 3 — Moduł A (A1–A2), Quiz, Moduł P (P1–P5) i Boss dla chętnych
-- Treść: docs/dzien3_zadania.md (wersja 2). 1:1.
-- Nie dotyka graczy, prób, biblioteki ani zadań innych dni.
-- Stare zadania Dnia 3 są wyłączane flagą active, nie usuwane.
-- Dnia 4 nie wyłączamy.
-- =====================================================

CREATE OR REPLACE FUNCTION public.level_lock(p_player_id uuid, p_level_id integer)
RETURNS jsonb
LANGUAGE sql
STABLE
SET search_path = ''
AS $$
  WITH lvl AS (
    SELECT l.id, l.module_id, l.sort_order, COALESCE(l.block, 1) AS block,
           m.day_number, m.unlocked, COALESCE(m.active_block, 1) AS active_block
    FROM public.levels l
    JOIN public.modules m ON m.id = l.module_id
    WHERE l.id = p_level_id AND l.active
  ),
  prev AS (
    SELECT p.id, p.code, p.title, p.config->>'label' AS label,
           CASE WHEN p.config ? 'quiz' THEN 0 WHEN p.config ? 'zones' THEN 90 ELSE 40 END AS pass_mark
    FROM public.levels p, lvl
    WHERE p.module_id = lvl.module_id
      AND p.active
      AND COALESCE(p.block, 1) = lvl.block
      AND (p.sort_order, p.id) < (lvl.sort_order, lvl.id)
    ORDER BY p.sort_order DESC, p.id DESC
    LIMIT 1
  )
  SELECT CASE
    WHEN NOT EXISTS (SELECT 1 FROM lvl) THEN jsonb_build_object('reason', 'missing')
    WHEN EXISTS (SELECT 1 FROM public.players WHERE id = p_player_id AND role IN ('admin', 'tester')) THEN jsonb_build_object('reason', null)
    WHEN (SELECT day_number > 1 AND NOT COALESCE(unlocked, false) FROM lvl) THEN jsonb_build_object('reason', 'module')
    WHEN (SELECT block > active_block FROM lvl) THEN jsonb_build_object('reason', 'block')
    WHEN EXISTS (SELECT 1 FROM prev)
     AND NOT EXISTS (SELECT 1 FROM public.battles b, prev
                     WHERE b.player_id = p_player_id AND b.level_id = prev.id
                       AND (b.score >= prev.pass_mark OR b.completed_via IS NOT NULL))
      THEN (SELECT jsonb_build_object('reason', 'previous', 'required',
                   jsonb_build_object('id', id, 'code', code, 'title', title, 'label', label)) FROM prev)
    ELSE jsonb_build_object('reason', null)
  END;
$$;

REVOKE ALL ON FUNCTION public.level_lock(uuid, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.level_lock(uuid, integer) TO service_role;

UPDATE public.levels SET active = false
WHERE module_id = (SELECT id FROM public.modules WHERE day_number = 3)
  AND (code IS NULL OR code NOT IN ('A1', 'A2', 'Q', 'P1', 'P2', 'P3', 'P4', 'P5', 'BOSS'));

UPDATE public.modules SET total_levels = 8, lives_enabled = false WHERE day_number = 3;

WITH day3 AS (
  SELECT id FROM public.modules WHERE day_number = 3
),
src (code, sort_order, block, type, title, xp_reward, task_description, config) AS (VALUES

('A1', 1, 1, 'solo', 'Odpowiedź na maila klienta', 100,
 $t$Napisz polecenie, które wpiszesz w Copilocie obok tego maila. Krótko: co ma napisać, jakim tonem i jak długo.$t$,
 $j${"label":"Ćwiczenie A1","block_name":"Moduł A · Poczta i dokumenty","department":"Dział handlowy","duration":"15 min","situation":"Klient napisał maila. Odpowiesz mu z pomocą Copilota w Outlooku. Copilot widzi maila, więc polecenie może być krótkie. Ale zawsze musi mieć: co napisać, jakim tonem i jak długo.","blocks":[{"title":"Mail klienta","text":"„Dzień dobry, zamówiłem 3 niszczarki (zamówienie ZAM/2026/031). Kiedy będzie dostawa? Chciałbym też porozmawiać o stałej współpracy. Pozdrawiam, [KLIENT]”"},{"title":"Fakty","lines":["Dostawa: 12 listopada.","Wolne terminy rozmowy: wtorek 10:00 albo czwartek 14:00."]}],"steps_title":"Co masz zrobić","steps":[{"text":"Napisz polecenie, które wpiszesz w Copilocie obok tego maila. Krótko: co ma napisać, jakim tonem i jak długo."}],"remember":["co ma napisać: potwierdzić dostawę 12 listopada","zaproponować 2 terminy rozmowy: wtorek 10:00 albo czwartek 14:00","ton (np. „uprzejmie i konkretnie”)","długość (np. „maksymalnie 80 słów”)"],"zones":{"green":["co ma napisać: potwierdzić dostawę 12 listopada","zaproponować 2 terminy rozmowy: wtorek 10:00 albo czwartek 14:00","ton (np. „uprzejmie i konkretnie”)","długość (np. „maksymalnie 80 słów”)"],"yellow":["Brakuje jednej lub dwóch rzeczy z listy."],"red":["Samo „odpisz mu” albo brakuje trzech lub więcej rzeczy. Także: dane z czerwonej strefy."]},"bonus":{"xp":25,"items":["Podajesz formę „Pan/Pani” albo podpis."]},"preview":{"messages":[{"role":"user","from_block":0,"label":"Mail klienta"}]},"reference":{"prompt":"Odpowiedz klientowi: potwierdź dostawę 12 listopada i zaproponuj rozmowę o stałej współpracy: wtorek 10:00 albo czwartek 14:00. Ton uprzejmy i konkretny, na „Pan/Pani”, maksymalnie 80 słów."},"other_example":{"situation":"Serwis odpowiada na pytanie o naprawę.","text":"Odpowiedz klientowi: drukarka będzie gotowa w piątek, odbiór w serwisie 8:00–16:00. Ton życzliwy, maksymalnie 60 słów."},"evaluator":"Oceniaj SENS, nie słowa. Literówki i synonimy się liczą. Przy wątpliwości wyższa strefa. ZIELONA = co najmniej 70% kryteriów i sedno. ŻÓŁTA = brakuje 1–2 rzeczy, ale jest próba. CZERWONA TYLKO ogólnik albo dane z czerwonej strefy. Wymagaj TYLKO listy „Nie zapomnij o”. Sprawdzasz tekst uczestnika, nie odpowiedź AI. Nie wymagaj roli ani kontekstu: Copilot widzi maila. KRYTERIA: 1 = potwierdzić dostawę 12 listopada; 2 = dwa terminy: wtorek 10:00 albo czwartek 14:00; 3 = ton; 4 = długość. BONUS: forma „Pan/Pani” albo podpis."}$j$::jsonb),

('A2', 2, 1, 'solo', 'Lista zadań ze spotkania', 100,
 $t$1. Napisz polecenie: AI ma zrobić z notatek listę zadań: kto, co i do kiedy.
